#include <bitset>
#include <string>
#include <iostream>

int main() {
    std::bitset<4> b(0b1011);

    // Default usage (MSB first: Index 3, 2, 1, 0)
    std::string s1 = b.to_string();
    std::cout << "Default: " << s1 << std::endl; // Output: 1011

    // Explicit template specification (required in dependent contexts):
    using default_traits = std::char_traits<char>;
    using default_alloc = std::allocator<char>;

    std::string s2 = b.template to_string<char, default_traits, default_alloc>();
    std::cout << "Explicit: " << s2 << std::endl;
}
